                {word}
                {index < words.length - 1 ? " " : ""}
              </span>
            );
          })}
        </div>
        <div
          style={{
            width: u * 16 * bar,
            height: u * 1,
            borderRadius: u,
            backgroundColor: brand.accent,
            margin: `${u * 4.5}px auto 0`,
          }}
        />
      </div>
    </AbsoluteFill>
  );
};
